-- 01_move_to_archive_schema.sql
-- Moves all 112 stored procedures and the 3 orphan scalar functions into an [archive] schema.
-- Reversible: ALTER SCHEMA dbo TRANSFER archive.<name> puts any object back.
-- Run inside a transaction; nothing is dropped.
SET XACT_ABORT ON;
BEGIN TRANSACTION;
IF SCHEMA_ID('archive') IS NULL EXEC('CREATE SCHEMA archive AUTHORIZATION dbo');

IF OBJECT_ID('dbo.ClearRouteDirections','P') IS NOT NULL ALTER SCHEMA archive TRANSFER dbo.[ClearRouteDirections];
IF OBJECT_ID('dbo.ClearRoutePictures','P') IS NOT NULL ALTER SCHEMA archive TRANSFER dbo.[ClearRoutePictures];
IF OBJECT_ID('dbo.DeleteRoutePicture','P') IS NOT NULL ALTER SCHEMA archive TRANSFER dbo.[DeleteRoutePicture];
