IF OBJECT_ID('dbo.GetAverageWindSpeed','P') IS NOT NULL ALTER SCHEMA archive TRANSFER dbo.[GetAverageWindSpeed];
IF OBJECT_ID('dbo.GetBikeById','P') IS NOT NULL ALTER SCHEMA archive TRANSFER dbo.[GetBikeById];
IF OBJECT_ID('dbo.GetBikeByName','P') IS NOT NULL ALTER SCHEMA archive TRANSFER dbo.[GetBikeByName];
